def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Calculate total sum
    total_sum = sum(a)

    # If total_sum is 1, we can't make all divisible by any k > 1
    if total_sum == 1 or total_sum == 0:
        return "-1\n"

    # If n == 1 and a[0] == 1, we can't move anywhere
    if n == 1 and a[0] == 1:
        return "-1\n"

    # Get all prime factors of total_sum
    prime_factors = get_prime_factors(total_sum)

    if not prime_factors:
        return "-1\n"

    min_seconds = float('inf')

    for k in prime_factors:
        # Calculate cost for this divisor k
        seconds = 0
        balance = 0
        for i in range(n):
            balance = (balance + a[i]) % k
            seconds += abs(balance)

        min_seconds = min(min_seconds, seconds)

    return f"{min_seconds}\n"

def get_prime_factors(n):
    """Return all unique prime factors of n"""
    factors = set()
    d = 2
    temp = n

    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1

    if temp > 1:
        factors.add(temp)

    return sorted(list(factors))

