    lines = input_str.strip().split('\n')
    n = int(lines[0].strip())
    a = list(map(int, lines[1].strip().split()))

    if n == 1 and a[0] <= 1:
        return "-1\n"

    if n == 1 and a[0] > 1:
        # Single box with more than 1 chocolate, we need k > 1 dividing a[0]
        # But we can't move anything, so we're already done if a[0] has a factor > 1
        gcd_val = a[0]
        for f in range(2, int(gcd_val**0.5) + 1):
            if gcd_val % f == 0:
                return "0\n"
        return "-1\n"

    S = sum(a)

    # Find all prime factors of S
    factors = set()
    d = 2
    temp = S
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)

    if not factors:
        return "-1\n"

    # Compute prefix sums
    prefix = [0] * n
    prefix[0] = a[0]
    for i in range(1, n):
        prefix[i] = prefix[i-1] + a[i]

    min_moves = float('inf')

    for k in factors:
        total_moves = 0
        for i, val in enumerate(prefix):
            rem = val % k
            if rem == 0:
                continue
            # Minimum movement: either move rem forward or k-rem backward
            if rem <= k // 2:
                total_moves += rem
            else:
                total_moves += k - rem

        if total_moves < min_moves:
            min_moves = total_moves

    return f"{min_moves}\n"

