def build_patterned_matrix(n, m):
    """
    Construct a matrix with bitonic rows and columns
    based on a pattern where values are placed in a snake-like manner
    """
    from itertools import permutations

    all_values = list(range(1, n * m + 1))

    # Try different orderings
    for order in permutations(all_values):
        result = [[0] * m for _ in range(n)]

        # Place values in snake pattern
        idx = 0
        for i in range(n):
            if i % 2 == 0:
                result[i] = list(order[idx:idx+m])
            else:
                result[i] = list(reversed(order[idx:idx+m]))
            idx += m

        if check_bitonic_matrix(result):
            return result

    # Fallback: simple bitonic construction
