        left = idx + peak
        right = idx + m - 1 - (peak + 1)
        result[i][peak] = mid_val

        # Place remaining around peak
        for _ in range(peak):
            result[i][_ * 2] = row_vals[_]
            result[i][peak + _ + 1] = row_vals[_ + m - peak - 1]

