def solution(input_str):
    """
    Solves the problem of finding maximum happy friends.

    Two friends are mutually incompatible if they appear in the same segment
    (between two type-1 change events). The problem reduces to finding the maximum
    subset of friends such that no two selected friends share any segment.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    segments = []
    current_segment = set()

    # Parse events
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if not parts:
            continue

        event_type = parts[0]
        if event_type == '1':
            segments.append(current_segment)
            current_segment = set()
        elif event_type == '2' and len(parts) > 1:
            current_segment.add(parts[1])
    segments.append(current_segment)

    if not segments:
        return '0'

    # Get all friends and map each friend to their segments
    friends = set()
    for seg in segments:
        friends.update(seg)

    if not friends:
        return '0'

    friends = sorted(friends)
    num_friends = len(friends)

    # For each friend, store which segment IDs they appear in
    friend_to_segments = {}
    for friend in friends:
        friend_to_segments[friend] = []

    for seg_idx, segment in enumerate(segments):
        for friend in segment:
            friend_to_segments[friend].append(seg_idx)

    # Two friends are compatible if their segment sets are disjoint
    # We use recursion with memoization to find max compatible subset

    memo = {}

    def solve(index, used_segments):
        if index == num_friends:
            return 0

        # Create a state key (index + sorted tuple of used segments)
        state = (index, tuple(used_segments))
        if state in memo:
            return memo[state]

        friend = friends[index]
        my_segments = friend_to_segments[friend]

        # Option 1: Skip this friend
        res = solve(index + 1, used_segments)

        # Option 2: Include this friend if segments are disjoint
        can_include = True
        for seg in my_segments:
            if seg in used_segments:
                can_include = False
                break

        if can_include:
            res = max(res, 1 + solve(index + 1, used_segments | set(my_segments)))

        memo[state] = res
        return res

    result = solve(0, set())
    return str(result)


