    def dinic_max_flow(n_nodes, edges, source, sink):
        G = [[] for _ in range(n_nodes)]
        for u, v, cap in edges:
            G[u].append([v, cap, len(G[v])])
            G[v].append([u, 0, len(G[u]) - 1])

        flow = 0
        while True:
            level = [-1] * n_nodes
            level[source] = 0
            q = deque([source])
