                        G[v][rev][1] += tr
                        total_pushed += tr
                        pushed -= tr
                    i += 1
                    ptr[u] = i
                return total_pushed

            while True:
                pushed = dfs(source, float('inf'))
                if pushed == 0:
                    break
                flow += pushed
        return flow

