    @lru_cache(maxsize=None)
    def solve(turn, available_mask):
        """
        Turn: current action index (0 to m-1)
        available_mask: bitmask where bit i is 1 if hero i is available

        Returns: maximum (team1_score - team2_score) from this state onwards
        """
        if turn == m:
            return 0

        action_type, team = actions[turn]

        # Get available hero indices
        available_heroes = [i for i in range(n) if not (available_mask & (1 << i))]

        if action_type == 'p':
            if team == 1:
                # Team 1 wants to maximize: their pick adds to team1_score
                return max(strengths[hero] + solve(turn + 1, available_mask ^ (1 << hero))
                          for hero in available_heroes)
            else:
                # Team 2 wants to minimize: their pick adds to team2_score (reduces diff)
                return min(solve(turn + 1, available_mask ^ (1 << hero))
                          - strengths[hero] for hero in available_heroes)
        else:  # action_type == 'b'
            if team == 1:
                # Team 1 bans, wants to maximize final outcome
                return max(solve(turn + 1, available_mask ^ (1 << hero))
                           for hero in available_heroes)
            else:
                # Team 2 bans, wants to minimize final outcome
                return min(solve(turn + 1, available_mask ^ (1 << hero))
                         for hero in available_heroes)

    return str(solve(0, 0))

