    """
    Solves the interactive game navigation problem.

    The problem involves navigating a grid where button functions may be swapped.
    We parse the input, find the finish position, and compute the shortest path
    while respecting the directional swaps.
    """
    lines = input_str.strip().split('\n')
    if not lines:
