    swapUD = int(first_line[3]) if len(first_line) > 3 else 0

    grid = []
    for i in range(1, n + 1):
        if i < len(lines):
            grid.append(lines[i])

    # Find finish position (1-indexed to 0-indexed)
    finish_pos = None
    for r in range(n):
        if r < len(grid):
            for c in range(m):
                if c < len(grid[r]):
                    if grid[r][c] == 'F':
                        finish_pos = (r, c)
                        break
        if finish_pos:
            break

    if finish_pos is None:
        return ""

    start_pos = (0, 0)  # 0-indexed

    # Try all 4 possible swap configurations
    for lr_swap in [0, swapLR]:
        for ud_swap in [0, swapUD]:
            # Build direction mappings (considering swaps)
            movement_map = []
            if ud_swap == 0 and lr_swap == 0:
                # Normal: U=(-1,0), D=(1,0), L=(0,-1), R=(0,1)
                movement_map = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            elif ud_swap == 0 and lr_swap == 1:
                # LR swapped: U=(-1,0), D=(1,0), L=(0,1), R=(0,-1)
                movement_map = [(-1, 0), (1, 0), (0, 1), (0, -1)]
            elif ud_swap == 1 and lr_swap == 0:
                # UD swapped: U=(1,0), D=(-1,0), L=(0,-1), R=(0,1)
                movement_map = [(1, 0), (-1, 0), (0, -1), (0, 1)]
            else:  # ud_swap == 1 and lr_swap == 1
                # Both swapped: U=(1,0), D=(-1,0), L=(0,1), R=(0,-1)
                movement_map = [(1, 0), (-1, 0), (0, 1), (0, -1)]
            # Direction order: U, D, L, R

            # BFS to find shortest path
            visited = set()
            visited.add(start_pos)
            queue = [(start_pos)]
            parent = {start_pos: None}
            target_dir = None
            found = False

            while queue:
                (r, c) = queue.pop(0)
                if (r, c) == finish_pos:
                    found = True
                    break

                for i, (dr, dc) in enumerate(movement_map):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
