def solution(input_string):
    lines = input_string.strip().split('\n')

    # Parse input
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    distances = list(map(int, lines[1].split()))
    heights = list(map(int, lines[2].split()))

    # Adjust to 0-indexed
    d = [0] * n  # d[i] is distance between tree i and i+1
    for i in range(n):
        d[i] = distances[i]

    h = heights

    # Precompute prefix distances
    # PD[i] = sum of first i distances (distance from tree 1 to tree i+1 going forward)
    # Actually: PD[0] = 0 (dist from tree 1 to itself = 0)
    # PD[1] = d[0] (dist from tree 1 to tree 2)
    # PD[i] = PD[i-1] + d[i-1] for i in 1..n-1

    PD = [0] * n
    for i in range(1, n):
        PD[i] = PD[i-1] + d[i-1]

    total_dist = sum(d)

    # P[i] for i in 0..n-1 (0-indexed): 2*h[i] - PD[i]
    # N[i] for i in 0..n-1: 2*h[i] + PD[i]
    P = [(2 * h[i]) - PD[i] for i in range(n)]
    N = [(2 * h[i]) + PD[i] for i in range(n)]

    # Prefix sums for quickly checking sums in a range
    # Actually, height sum isn't critical for energy within formula

    # Build segment trees
    # For a range [L, R], store:
    # - p_max = max P value in range
    # - n_max = max N value in range  
    # - pair_max = max P[a] + N[b] for L <= a < b <= R

    INF = float('-inf')

    class SegmentTree:
        def __init__(self, P, N):
            self.n = len(P)
            self.tree = [
                {'p_max': INF, 'n_max': INF, 'pair_max': INF} 
                for _ in range(4 * self.n)
            ]
            self.build(P, N, 1, 0, self.n - 1)

        def build(self, P, N, node, L, R):
            if L == R:
                self.tree[node] = {
                    'p_max': P[L],
                    'n_max': N[L],
                    'pair_max': INF
                }
            else:
                mid = (L + R) // 2
                self.build(P, N, 2 * node, L, mid)
                self.build(P, N, 2 * node + 1, mid + 1, R)

                left = self.tree[2 * node]
                right = self.tree[2 * node + 1]

                self.tree[node] = {
                    'p_max': max(left['p_max'], right['p_max']),
                    'n_max': max(left['n_max'], right['n_max']),
                    'pair_max': max(left['pair_max'], right['pair_max'], 
                                   left['p_max'] + right['n_max'])
                }

        def query(self, L, R):
            return self._query(1, 0, self.n - 1, L, R)

        def _query(self, node, tree_L, tree_R, qL, qR):
            if qL > tree_R or qR < tree_L:
                return {'p_max': INF, 'n_max': INF, 'pair_max': INF}
            if qL <= tree_L and qR >= tree_R:
                return self.tree[node]
            mid = (tree_L + tree_R) // 2
            left = self._query(2 * node, tree_L, mid, qL, qR)
            right = self._query(2 * node + 1, mid + 1, tree_R, qL, qR)

            return {
                'p_max': max(left['p_max'], right['p_max']),
                'n_max': max(left['n_max'], right['n_max']),
                'pair_max': max(left['pair_max'], right['pair_max'],
                               left['p_max'] + right['n_max'])
            }

    seg_tree = SegmentTree(P, N)

    results = []

    for _ in range(m):
        line = lines[3 + _].split()
        a, b = int(line[0]) - 1, int(line[1]) - 1  # 0-indexed

        if a > b:
            # Children in [a, n-1] U [0, b], free is [b+1, a]
            l, r = b + 1, a
            if l > r:
                # Should not happen based on problem constraints
                results.append("0")
                continue

            res = seg_tree.query(l, r)
            if res['pair_max'] == INF:
                results.append("0")
            else:
                results.append(str(res['pair_max']))
        else:
            # If a <= b: free is [0, a-1] and [b+1, n-1]
            # Case a == b: free is [0, a-1] and [a+1, n-1]

            # Free range 1: [0, a-1]
            if a > 0:
                p1 = seg_tree.query(0, a - 1)
            else:
                p1 = {'p_max': INF, 'n_max': INF, 'pair_max': INF}

            # Free range 2: [b+1, n-1]
            if b + 1 < n:
                p2 = seg_tree.query(b + 1, n - 1)
            else:
                p2 = {'p_max': INF, 'n_max': INF, 'pair_max': INF}

            # Case 1: both trees in range 1
            if p1['pair_max'] != INF:
                ans1 = p1['pair_max']
            else:
                ans1 = INF

            # Case 2: both trees in range 2  
            if p2['pair_max'] != INF:
                ans2 = p2['pair_max']
            else:
                ans2 = INF

            # Case 3: one tree in each range (cross)
            # Energy = P[x] + N[y] + total_dist
            cross = INF
            if p1['p_max'] != INF and p2['n_max'] != INF:
                cross = p1['p_max'] + p2['n_max'] + total_dist

            ans = max(ans1, ans2, cross)
            results.append(str(int(ans)))

    return '\n'.join(results)

