def reverse_num(n):
    """Reverse the decimal representation of n, removing leading zeros"""
    return int(str(n)[::-1])

def rational(n, m):
    """Return irreducible fraction as tuple"""
    g = math.gcd(n, m)
    return (n // g, m // g)

